inline std::vector<SceneVertex> BuildSteeringWheel(SceneRenderer& renderer,float radius) {
    static const auto image=gt2::DecodePng(kSteeringWheelPng);
    if(image.width<=0||image.height<=0||uint64_t(image.width)*image.height>(1u<<20))throw std::runtime_error("steering wheel texture exceeds reserved range");
    std::vector<uint32_t> pixels(size_t(image.width)*image.height);std::memcpy(pixels.data(),image.rgba.data(),pixels.size()*4);
    renderer.UploadExternalTexture(SceneRenderer::kVrHandTexelBase,uint32_t(pixels.size()),pixels.data());
    std::vector<SceneVertex> result;result.reserve(std::size(kSteeringWheelIndices));
    for(auto index:kSteeringWheelIndices){const auto& p=kSteeringWheelVertices[index];SceneVertex v{};
        for(int i=0;i<3;++i){v.pos[i]=p[i]*radius;v.color[i]=1;}
        v.texel[0]=p[3]*image.width;v.texel[1]=p[4]*image.height;
        v.page=SceneRenderer::kVrHandTexelBase;v.clut=uint32_t(image.width)|(uint32_t(image.height)<<16);
        v.flags=kTextured|kExternalTexture|kModelClampU|kModelClampV;result.push_back(v);
    }return result;
}
